import { useProgressiveRows } from '@/hooks/useProgressiveRows';
import { InfoTip } from '@/components/ui/InfoTip';
import { useMemo, useState } from 'react';
import FitName from '../FitName';
import { BarChart3, ListOrdered, Table2 } from 'lucide-react';
import type { Player, Position } from '@/types/player';
import { cn } from '@/lib/utils';
import { useStagger } from '@/utils/motion';
import { evaluateMetric, metricsFor, placeOnBoard, type AdvContext, type MetricRow } from '@/config/advanced';
import { POSITION_NAMES } from '@/utils/playerMeta';
import TeamLogo from '../../brand/TeamLogo';
import MetricLabel from './MetricLabel';
import PercentileBar from './PercentileBar';
import Chips from './Chips';
import { fmtNum, fmtPlus, ordinal } from './viz';
import { keyOf } from '../records';
import PlusLollipop from '../visual/PlusLollipop';
import { peekProps } from '@/components/peek/peekProps';
import { displayName } from '@/utils/displayName';

const SHOWN = 12;

interface Props {
  players: Player[];
  ctx: AdvContext;
  position: Position;
  /** Real NFL legends placed on the league board (unranked; the board itself never changes). */
  extras?: Player[];
  onSelect: (p: Player) => void;
}

/** A leaderboard row; real NFL players are unranked (rank 0) and flagged. */
export type BoardRow = MetricRow & { nfl?: boolean };

const NflTag = () => <span className="rounded-sm bg-flag/80 px-1 font-pixel text-[7px] leading-tight text-night">NFL</span>;

/** Position leaderboard for any advanced metric: value, + index and percentile per qualifier. */
const MetricLeaderboard = ({ players, ctx, position, extras = [], onSelect }: Props) => {
  const metrics = metricsFor(position);
  const [picked, setPicked] = useState<Partial<Record<Position, string>>>({});
  const [expanded, setExpanded] = useState(false);
  const [asTable, setAsTable] = useState(false);
  // Rows stagger in once; "Show all" and metric changes only fade new rows in
  const rowMotion = useStagger();
  const metric = metrics.find((m) => m.id === picked[position]) ?? metrics[0];
  const board = useMemo(() => evaluateMetric(players, metric, position, ctx), [players, metric, position, ctx]);
  const merged: BoardRow[] = useMemo(() => {
    const placed = extras
      .map((p) => placeOnBoard(board, p, ctx))
      .filter((r): r is NonNullable<typeof r> => !!r)
      .map((r) => ({ ...r, rank: 0, nfl: true }));
    if (!placed.length) return board.rows;
    return [...board.rows, ...placed].sort((a, b) => (metric.lowerIsBetter ? a.value - b.value : b.value - a.value));
  }, [board, extras, ctx, metric]);
  const nflCount = merged.length - board.rows.length;
  const rowWindow = useProgressiveRows(merged.length, { initial: 60, step: 100, resetKey: `${metric.id}|${position}|${expanded}` });
  const rows = expanded ? (asTable ? merged.slice(0, rowWindow.shown) : merged) : merged.slice(0, SHOWN);
  const suffix = metric.suffix ?? '';

  return (
    <section aria-labelledby="lab-board-title" className="glass-card flex min-w-0 flex-col gap-3 p-3 sm:p-4">
      <div className="flex flex-wrap items-start justify-between gap-2">
        <div className="min-w-0 flex-1">
          <h3 id="lab-board-title" className="flex items-center gap-2 font-display text-lg font-bold uppercase tracking-wide">
            <ListOrdered className="h-4 w-4 text-gold" aria-hidden="true" />
            {POSITION_NAMES[position]} leaderboard
          </h3>
          <p className="mt-0.5 flex items-center gap-1 text-xs text-muted-foreground sm:text-sm">
            Pick a metric
            <InfoTip>
              Each stem runs from the position average (dashed) to the player on the <b className="text-foreground">+</b> index axis
              (100 = average qualifier, 120 = 20% better): blue right of the line is better, red left is worse. The table adds percentiles.
            </InfoTip>
          </p>
        </div>
        <button
          type="button"
          aria-pressed={asTable}
          onClick={() => setAsTable((v) => !v)}
          className="inline-flex shrink-0 items-center gap-1.5 rounded-md border border-line bg-night/60 px-2 py-1 text-xs font-semibold text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-gold"
        >
          {asTable ? <BarChart3 className="h-3.5 w-3.5" aria-hidden="true" /> : <Table2 className="h-3.5 w-3.5" aria-hidden="true" />}
          {asTable ? 'Chart' : 'Table'}
          <span className="sr-only"> view for the leaderboard</span>
        </button>
      </div>

      <Chips
        label="Metric"
        value={metric.id}
        onChange={(id) => {
          setPicked((s) => ({ ...s, [position]: id }));
          setExpanded(false);
        }}
        options={metrics.map((m) => ({ value: m.id, label: m.short, title: m.label }))}
      />

      <div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1 border-y border-line/70 py-2 text-sm">
        <MetricLabel metric={metric} className="font-display font-bold uppercase tracking-wide text-foreground" />
        <span className="font-pixel text-[9px] uppercase text-muted-foreground">
          {metric.minLabel} · avg {fmtNum(board.mean, metric.decimals)}
          {suffix}
        </span>
      </div>

      {board.rows.length === 0 ? (
        <p className="py-6 text-center text-sm text-muted-foreground">No {position} meets the minimum sample yet.</p>
      ) : !asTable ? (
        <PlusLollipop board={board} rows={rows} allRows={merged} onSelect={onSelect} />
      ) : (
        <table className="rv-pin w-full table-fixed text-sm">
          <caption className="sr-only">
            {POSITION_NAMES[position]}s ranked by {metric.label} ({metric.minLabel})
          </caption>
          <thead>
            <tr className="text-left font-pixel text-[9px] uppercase text-muted-foreground">
              <th scope="col" className="w-7 pb-1 font-normal">
                #
              </th>
              <th scope="col" className="pb-1 font-normal">
                Player
              </th>
              <th scope="col" className="w-16 pb-1 text-right font-normal">
                {metric.short}
              </th>
              <th scope="col" className="w-11 pb-1 text-right font-normal">
                <abbr title="Position index, 100 = average" className="no-underline">
                  +
                </abbr>
              </th>
              <th scope="col" className="hidden w-[28%] pb-1 pl-3 font-normal sm:table-cell">
                Percentile
              </th>
            </tr>
          </thead>
          <tbody className={rowMotion}>
            {rows.map((r) => (
              <tr key={`${r.nfl ? 'nfl:' : ''}${keyOf(r.player)}`} className="group border-t border-line/40">
                <td className={cn('py-1.5 font-pixel text-[10px]', r.rank === 1 ? 'text-gold' : 'text-muted-foreground')}>{r.nfl ? <NflTag /> : r.rank}</td>
                <td className="py-1.5">
                  <button
                    type="button"
                    {...peekProps(r.player)}
                    onClick={() => onSelect(r.player)}
                    className="flex w-full min-w-0 items-center gap-1.5 rounded text-left font-semibold hover:text-gold focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-gold"
                  >
                    {r.player.team ? <TeamLogo team={r.player.team} size={18} decorative backed /> : <span className="w-[18px]" aria-hidden="true" />}
                    <span className="truncate"><FitName name={displayName(r.player.name)} /></span>
                    {r.nfl && <span className="sr-only">, real NFL player, unranked</span>}
                  </button>
                  {/* Mobile: percentile under the name */}
                  <PercentileBar
                    pct={r.pct}
                    label={`${displayName(r.player.name)} percentile`}
                    className="mt-1 h-1.5 w-full overflow-hidden rounded-sm sm:hidden"
                  />
                </td>
                <td className="py-1.5 text-right font-mono font-bold tabular-nums text-chalk">
                  {fmtNum(r.value, metric.decimals)}
                  {suffix}
                </td>
                <td className="py-1.5 text-right font-mono tabular-nums text-secondary-foreground">{fmtPlus(r.plus)}</td>
                <td className="hidden py-1.5 pl-3 sm:table-cell">
                  <div className="flex items-center gap-2">
                    <PercentileBar pct={r.pct} label={`${displayName(r.player.name)} percentile`} className="h-2 flex-1 overflow-hidden rounded-sm" />
                    <span className="w-8 text-right font-mono text-[11px] tabular-nums text-muted-foreground">{ordinal(r.pct)}</span>
                  </div>
                </td>
              </tr>
            ))}
            {expanded && asTable && rowWindow.more > 0 && (
              <tr ref={rowWindow.sentinelRef}>
                <td colSpan={5} className="py-2 text-center">
                  <button type="button" onClick={rowWindow.showMore} className="text-xs font-semibold uppercase tracking-wider text-gold hover:underline">
                    Show more ({rowWindow.more.toLocaleString()} left)
                  </button>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      )}

      <div className="mt-auto flex flex-wrap items-center justify-between gap-2 text-xs text-muted-foreground">
        <span>
          {board.rows.length} qualified{board.belowMin > 0 ? ` · ${board.belowMin} below ${metric.minLabel}` : ''}
          {nflCount > 0 ? ` · ${nflCount} real NFL shown unranked (percentile = share of the league they beat)` : ''}
        </span>
        {merged.length > SHOWN && (
          <button
            type="button"
            aria-expanded={expanded}
            onClick={() => setExpanded((v) => !v)}
            className="link-chip text-gold"
          >
            {expanded ? `Show top ${SHOWN}` : `Show all ${merged.length}`}
          </button>
        )}
      </div>
    </section>
  );
};

export default MetricLeaderboard;
